// Llega de los sitios (navigator.sendBeacon o fetch; campo d = JSON). Solo dominios propios.
// CONFIGURA: qué dominio es de qué marca y qué correos son de prueba.
const DOMINIOS = { '__DOMINIO_A__': 'marca-a', '__DOMINIO_B__': 'marca-b' };
const PRUEBAS = /@(__DOMINIO_A__|__DOMINIO_B__)$/;
const j = $input.first().json || {};
const h = j.headers || {};
const b = j.body || {};
let d = {};
try { d = typeof b.d === 'string' ? JSON.parse(b.d) : (b.d || b); } catch (e) { return []; }
const origen = String(h.origin || h.referer || d.pagina || '').toLowerCase();
const dom = Object.keys(DOMINIOS).find(k => origen.includes(k));
if (!dom) return [];
const marca = d.marca && Object.values(DOMINIOS).includes(d.marca) ? d.marca : DOMINIOS[dom];
const f = {};
for (const [k, v] of Object.entries(d.campos || {})) {
  const key = String(k).normalize('NFD').replace(/[̀-ͯ]/g, '').toLowerCase().replace(/[^a-z0-9]+/g, '_').replace(/^_|_$/g, '');
  if (v !== '' && v != null) f[key] = String(v).slice(0, 2000);
}
if (f._gotcha || f.gotcha) return [];
const take = (...ks) => { for (const k of ks) if (f[k]) { const v = f[k]; delete f[k]; return v; } return ''; };
const nombre = take('nombre', 'nombre_y_apellido', 'name');
const correo = take('email', 'correo').toLowerCase();
const telefono = take('telefono', 'tel', 'phone').replace(/[^0-9+]/g, '');
const empresa = take('empresa', 'company');
const mensaje = take('mensaje', 'comentarios', 'message');
const tipo = take('tipo');
['sitio', '_subject', 'subject'].forEach(k => delete f[k]);
const a = d.atribucion || {};
const texto = [nombre, correo, empresa, mensaje].join(' ');
const prueba = !!d.prueba || /\bprueba\b|\btest\b|no contactar/i.test(texto) || PRUEBAS.test(correo);
const eid = String(d.event_id || '').slice(0, 80);
const ahora = $now.setZone('America/Mexico_City');
const xff = String(h['x-forwarded-for'] || h['x-real-ip'] || '').split(',')[0].trim();
return [{ json: {
  lead_id: marca + '-' + (eid || ahora.toMillis()),
  fecha: ahora.toFormat('yyyy-MM-dd HH:mm:ss'), marca, origen: 'web_form',
  estado: prueba ? 'descartado' : 'nuevo',
  nombre, telefono, correo, empresa, mensaje, tipo,
  detalle: Object.keys(f).length ? JSON.stringify(f).slice(0, 2000) : '',
  pagina: String(d.pagina || '').slice(0, 500), landing: String(a.landing || '').slice(0, 500), referrer: String(a.referrer || '').slice(0, 500),
  utm_source: a.utm_source || '', utm_medium: a.utm_medium || '', utm_campaign: a.utm_campaign || '', utm_content: a.utm_content || '', utm_term: a.utm_term || '',
  gclid: a.gclid || '', fbclid: a.fbclid || '', fbp: d.fbp || '', fbc: d.fbc || '', event_id: eid,
  notas: prueba ? 'prueba (excluida)' : '', actualizado: ahora.toFormat('yyyy-MM-dd HH:mm:ss'),
  _ip: xff, _ua: String(h['user-agent'] || '').slice(0, 400), _ts: Math.floor(ahora.toSeconds()), _prueba: prueba
} }];

// Leads de los formularios instantáneos de Meta (uno por marca). Se guardan con origen meta_form.
// No se mandan a Conversions API (Meta ya los tiene); sí avisan si son de las últimas 24 h.
const PRUEBAS = /@(__DOMINIO_A__|__DOMINIO_B__)$/;
const z = 'America/Mexico_City', ahora = $now.setZone(z);
const ya = new Set($('Leer Leads').all().map(i => String((i.json || {}).lead_id || '')));
const out = [], errores = [];
const norm = s => String(s || '').normalize('NFD').replace(/[̀-ͯ]/g, '').toLowerCase().replace(/[^a-z0-9]+/g, '_').replace(/^_|_$/g, '');
for (const [nodo, marca] of [['Meta: formularios A', 'marca-a'], ['Meta: formularios B', 'marca-b']]) {
  let j = {};
  try { j = $(nodo).first().json || {}; } catch (e) { continue; }
  if (j.error) { errores.push(marca + ': ' + (j.error.message || JSON.stringify(j.error)).slice(0, 200)); continue; }
  for (const f of j.data || []) {
    for (const l of ((f.leads || {}).data || [])) {
      const id = marca + '-mf-' + l.id;
      if (ya.has(id)) continue;
      const c = {};
      for (const x of l.field_data || []) c[norm(x.name)] = (x.values || []).join(', ').slice(0, 1000);
      const take = (...ks) => { for (const k of ks) if (c[k]) { const v = c[k]; delete c[k]; return v; } return ''; };
      const nombre = take('full_name', 'nombre_completo', 'nombre') || [take('first_name'), take('last_name')].filter(Boolean).join(' ');
      const telefono = take('phone_number', 'telefono', 'celular').replace(/[^0-9+]/g, '');
      const correo = take('email', 'correo', 'work_email').toLowerCase();
      const empresa = take('company_name', 'empresa');
      const texto = JSON.stringify(l.field_data || []);
      const prueba = /<test lead|dummy data|\bprueba\b|\btest\b/i.test(texto) || PRUEBAS.test(correo);
      const dt = DateTime.fromISO(String(l.created_time || '').replace(/\+0000$/, 'Z')).setZone(z);
      const reciente = dt.isValid && ahora.diff(dt, 'hours').hours < 24;
      out.push({ json: {
        lead_id: id, fecha: (dt.isValid ? dt : ahora).toFormat('yyyy-MM-dd HH:mm:ss'), marca, origen: 'meta_form',
        estado: prueba ? 'descartado' : 'nuevo', nombre, telefono, correo, empresa, mensaje: '', tipo: 'formulario de Meta',
        detalle: JSON.stringify(Object.assign({ formulario: f.name, form_id: f.id }, l.ad_name ? { anuncio: l.ad_name } : {}, l.campaign_name ? { campana: l.campaign_name } : {}, c)).slice(0, 2000),
        pagina: '', landing: '', referrer: '', utm_source: 'meta', utm_medium: 'formulario', utm_campaign: String(l.campaign_name || ''), utm_content: String(l.ad_name || ''), utm_term: '',
        gclid: '', fbclid: '', fbp: '', fbc: '', event_id: '',
        notas: prueba ? 'prueba (excluida)' : (reciente ? '' : 'formulario de Meta, llegó con retraso'),
        actualizado: ahora.toFormat('yyyy-MM-dd HH:mm:ss'), _ip: '', _ua: '', _ts: Math.floor((dt.isValid ? dt : ahora).toSeconds()), _prueba: prueba || !reciente
      } });
    }
  }
}
if (errores.length) { const st = $getWorkflowStaticData('global'); const k = 'mf_err_' + ahora.toFormat('yyyy-MM-dd'); if (!st[k]) { st[k] = 1; throw new Error('No pude leer los formularios de Meta: ' + errores.join(' | ')); } }
return out.sort((a, b) => a.json._ts - b.json._ts);

// Solo leads reales y recientes: aviso en Telegram y, si vienen del sitio con event_id, Conversions API.
const NOMBRES = { 'marca-a': 'Marca A', 'marca-b': 'Marca B' };
const e = s => String(s || '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const out = [];
for (const it of $('Unir').all()) {
  const l = it.json;
  if (l._prueba) continue;
  const fuente = l.gclid ? 'Google Ads' : (l.fbclid || l.fbc) ? 'Meta' : l.utm_source ? (l.utm_source + (l.utm_medium ? ' / ' + l.utm_medium : '')) : (l.referrer ? 'referido: ' + l.referrer.replace(/^https?:\/\//, '').split('/')[0] : 'directo o sin dato');
  const texto = '🧲 <b>Lead nuevo · ' + e(NOMBRES[l.marca] || l.marca) + '</b>\n' + e(l.nombre) + (l.empresa ? ' · ' + e(l.empresa) : '') + (l.tipo ? '\nTipo: ' + e(l.tipo) : '') + (l.mensaje ? '\n«' + e(l.mensaje.slice(0, 200)) + '»' : '') + '\nFuente: ' + e(fuente) + (l.notas ? '\n<i>' + e(l.notas) + '</i>' : '') + '\nDatos de contacto en el Sheet, pestaña Leads.';
  const capi = !!l.event_id;
  const evento = { event_name: 'Lead', event_time: l._ts, event_id: l.event_id, action_source: 'website', event_source_url: l.pagina || undefined,
    user_data: Object.fromEntries(Object.entries({ client_ip_address: l._ip, client_user_agent: l._ua, fbp: l.fbp, fbc: l.fbc }).filter(([, v]) => v)) };
  out.push({ json: { lead_id: l.lead_id, marca: l.marca, capi, texto, capi_body: { data: [evento] } } });
}
return out;
